{
  "ledger": {
    "p29:e201": {
      "state": "represented",
      "fact_ids": ["P0029R0F0001"],
      "note": "spMM 도입 후 결과 확인 행위가 P0029R0F0001에 보존됨. 결과 수치 자체는 이 요소에 없고 p30:e202/p30:enh:e0에 존재."
    },
    "p29:enh:e0": {
      "state": "represented",
      "fact_ids": ["P0029R0F0003"],
      "note": "27ms 관찰, 24ms 기준선 언급, 세 가지 질문/혼란 표현 모두 P0029R0F0003에 보존됨."
    },
    "p29:enh:e1": {
      "state": "represented",
      "fact_ids": ["P0029R0F0006"],
      "note": "오후 8:14 타임스탬프 메타데이터로 보존됨. 연구 내용 아님."
    },
    "p29:enh:e2": {
      "state": "represented",
      "fact_ids": ["P0029R0F0004"],
      "note": "cuSPARSE 확장 중단 권고, 24ms baseline 복귀, 별도 실험 유지 권고 모두 보존됨."
    },
    "p29:enh:e3": {
      "state": "represented",
      "fact_ids": ["P0029F0001"],
      "note": "느려진 이유가 cuSPARSE 최적화 부족이 아니라 workload 불리함 때문이라는 해석 보존됨."
    },
    "p29:enh:e4": {
      "state": "represented",
      "fact_ids": ["P0029F0002"],
      "note": "목록 5개 항목(작은 행렬/3개 layer, 적은 SpMV 호출로 kernel/descriptor 비용 큼, cusparseDnVec 생성·삭제·buffer 계산, D2H→CPU vec_add→H2D, 대규모 throughput vs 작은 latency에서 custom kernel 우위) 모두 보존됨."
    },
    "p29:enh:e5": {
      "state": "represented",
      "fact_ids": ["P0029F0003"],
      "note": "cuSPARSE 적용 부분이 network_forward()의 W*x 뿐이며 전체 24ms 중 일부만 영향받고 그 일부에 오버헤드 추가됐다는 설명 보존됨. 24ms는 기준선 언급."
    },
    "p29:enh:e6": {
      "state": "represented",
      "fact_ids": ["P0029F0004", "P0029R0F0005"],
      "note": "중복 표현 존재. P0029R0F0005가 '24 ms 버전 기준 유지' 문장까지 포함해 더 완전함. P0029F0004는 해당 문장이 누락된 부분 중복."
    },
    "p29:enh:e7": {
      "state": "represented",
      "fact_ids": ["P0029R0F0001"],
      "note": "p29:e201과 동일 문장이므로 P0029R0F0001에서 함께 보존됨."
    }
  }
}
